"""FastAPI app — REST endpoints + /ws live push. No route here can construct
or broadcast a real transaction; see trading/exchange.py.
"""
from __future__ import annotations

from pathlib import Path

from fastapi import FastAPI, WebSocket, WebSocketDisconnect
from fastapi.responses import FileResponse, JSONResponse
from fastapi.staticfiles import StaticFiles

from ..app import AppContext
from . import viewmodel as vm
from .systems_catalog import SYSTEM_GROUPS

FRONTEND_DIR = Path(__file__).resolve().parent.parent.parent / "frontend"


def create_app(ctx: AppContext) -> FastAPI:
    app = FastAPI(title="STORMCHASER")

    @app.on_event("startup")
    async def _startup():
        await ctx.start()

    @app.on_event("shutdown")
    async def _shutdown():
        await ctx.stop()

    # -- reads -----------------------------------------------------------

    @app.get("/api/ticker")
    async def ticker():
        return vm.ticker_payload(ctx)

    @app.get("/api/tokens")
    async def tokens():
        return vm.tokens_list_payload(ctx)

    @app.get("/api/tokens/{symbol}")
    async def token_detail(symbol: str):
        payload = vm.token_detail_payload(ctx, symbol)
        if payload is None:
            return JSONResponse({"error": "unknown symbol"}, status_code=404)
        return payload

    @app.get("/api/positions")
    async def positions():
        return vm.positions_payload(ctx)

    @app.get("/api/journal")
    async def journal():
        return vm.journal_payload(ctx)

    @app.get("/api/storm-log")
    async def storm_log():
        return vm.storm_log_payload(ctx)

    @app.get("/api/systems")
    async def systems():
        groups = [{"title": g["title"], "items": [
            {"num": n, "name": name, "status": status, "blurb": blurb, "stat": stat}
            for n, name, status, blurb, stat in g["items"]
        ]} for g in SYSTEM_GROUPS]
        active = sum(1 for g in groups for i in g["items"] if i["status"] == "ARMED")
        total = sum(len(g["items"]) for g in groups)
        return {"groups": groups, "active_count": active, "total_count": total}

    @app.get("/api/settings")
    async def settings():
        return vm.settings_payload(ctx)

    # -- trading (paper only — see trading/exchange.py) ----------------------

    @app.post("/api/trade")
    async def trade(payload: dict):
        symbol = payload.get("symbol")
        side = payload.get("side")
        sol_amount = payload.get("sol_amount")
        mode = ctx.ui_state["mode"]
        t = ctx.hub.token_by_symbol(symbol) if symbol not in ("SOL", "BTC") else {"address": symbol}
        if not t and symbol not in ("SOL", "BTC"):
            return JSONResponse({"status": "rejected", "reject_reason": "unknown token"}, status_code=404)
        import stormchaser.sim as sim
        blocked = ctx.ui_state["exit_only"] or ctx.ui_state["paused"]
        block_reason = "exit-only mode" if ctx.ui_state["exit_only"] else "entries paused"
        if not blocked and side == "buy" and symbol not in ("SOL", "BTC"):
            fc = sim.forecast(symbol, t["address"], t["change_pct"], t.get("volume_usd"), t.get("liquidity_usd"))
            if fc["risk"] == "SEVERE":
                blocked, block_reason = True, "storm lock — coordinated pump detected"
        wallet_id = ctx.wallets[mode]["id"]
        result = ctx.exchange.execute(
            wallet_id=wallet_id, mode=mode, symbol=symbol, address=(t or {}).get("address", ""),
            side=side, sol_amount=sol_amount, qty=payload.get("qty"), blocked=blocked,
            block_reason=block_reason)
        return result

    @app.post("/api/approvals/{approval_id}/approve")
    async def approve(approval_id: int):
        return ctx.copilot.approve(approval_id)

    @app.post("/api/approvals/{approval_id}/reject")
    async def reject(approval_id: int):
        ctx.copilot.reject(approval_id)
        return {"status": "rejected"}

    @app.post("/api/panic")
    async def panic():
        st = ctx.ui_state
        st["panic"] = 0 if st["panic"] == 2 else st["panic"] + 1
        if st["panic"] == 2:
            wallet_id = ctx.wallets[st["mode"]]["id"]
            for p in ctx.db.open_positions(wallet_id):
                t = ctx.hub.token_by_symbol(p["symbol"])
                if not t:
                    continue
                ctx.exchange.execute(wallet_id=wallet_id, mode=st["mode"], symbol=p["symbol"],
                                     address=p["address"], side="sell", qty=p["qty"])
        return {"panic": st["panic"]}

    @app.post("/api/panic/reset")
    async def panic_reset():
        ctx.ui_state["panic"] = 0
        return {"panic": 0}

    # -- controls -------------------------------------------------------------

    @app.post("/api/controls/mode")
    async def set_mode(payload: dict):
        mode = payload.get("mode", "ghost").lower()
        if mode not in ("ghost", "copilot"):
            return JSONResponse({"error": "invalid mode — only ghost/copilot exist in this build"}, status_code=400)
        ctx.ui_state["mode"] = mode
        return {"mode": mode.upper()}

    @app.post("/api/controls/pause")
    async def toggle_pause():
        ctx.ui_state["paused"] = not ctx.ui_state["paused"]
        return {"paused": ctx.ui_state["paused"]}

    @app.post("/api/controls/exit-only")
    async def toggle_exit_only():
        ctx.ui_state["exit_only"] = not ctx.ui_state["exit_only"]
        return {"exit_only": ctx.ui_state["exit_only"]}

    @app.post("/api/settings/theme")
    async def set_theme(payload: dict):
        theme = payload.get("theme", "EVA UNIT-01")
        ctx.ui_state["theme"] = theme
        ctx.db.set_setting("theme", theme)
        return {"theme": theme}

    @app.post("/api/settings/scanlines")
    async def set_scanlines(payload: dict):
        on = bool(payload.get("on", True))
        ctx.ui_state["scanlines"] = on
        ctx.db.set_setting("scanlines", "1" if on else "0")
        return {"scanlines": on}

    # -- ws ---------------------------------------------------------------

    @app.websocket("/ws")
    async def ws_endpoint(ws: WebSocket):
        await ws.accept()
        ctx.register_ws(ws)
        try:
            await ws.send_json(vm.ticker_payload(ctx))
            while True:
                await ws.receive_text()
        except WebSocketDisconnect:
            pass
        finally:
            ctx.unregister_ws(ws)

    # -- static frontend --------------------------------------------------

    app.mount("/static", StaticFiles(directory=str(FRONTEND_DIR)), name="static")

    @app.get("/")
    async def index():
        return FileResponse(str(FRONTEND_DIR / "index.html"))

    @app.get("/{filename}")
    async def frontend_file(filename: str):
        f = FRONTEND_DIR / filename
        if f.is_file():
            return FileResponse(str(f))
        return FileResponse(str(FRONTEND_DIR / "index.html"))

    return app

