"""CoinGecko free API client (no key). One /coins/markets call covers BTC + SOL,
including a 7d sparkline — this is real market data, not simulated.
"""
from __future__ import annotations

import httpx

from .ratelimit import TokenBucket

BASE = "https://api.coingecko.com/api/v3"


class CoinGeckoClient:
    BACKOFF_S = 120  # sit out this long after a 429 — free tier is unforgiving

    def __init__(self, rate_per_min: float = 8):
        self.bucket = TokenBucket(rate_per_min, burst=3)
        self.http = httpx.AsyncClient(timeout=15, headers={"User-Agent": "stormchaser/1.0"})
        self._blocked_until = 0.0

    async def close(self) -> None:
        await self.http.aclose()

    async def _get(self, path: str, params: dict) -> list | dict | None:
        import time as _t
        if _t.monotonic() < self._blocked_until:
            return None
        await self.bucket.acquire()
        try:
            resp = await self.http.get(f"{BASE}{path}", params=params)
            if resp.status_code == 429:
                self._blocked_until = _t.monotonic() + self.BACKOFF_S
                return None
            resp.raise_for_status()
            return resp.json()
        except httpx.HTTPError:
            return None

    async def markets(self, ids: tuple[str, ...]) -> dict[str, dict]:
        """coin_id -> trimmed row (price, 24h change, 7d sparkline). {} on failure."""
        data = await self._get("/coins/markets", {
            "vs_currency": "usd",
            "ids": ",".join(ids),
            "sparkline": "true",
            "price_change_percentage": "24h",
        })
        if not isinstance(data, list):
            return {}
        out = {}
        for row in data:
            spark = ((row.get("sparkline_in_7d") or {}).get("price")) or []
            out[row["id"]] = {
                "price_usd": row.get("current_price") or 0.0,
                "change_pct": row.get("price_change_percentage_24h") or 0.0,
                "sparkline": spark[-24:],  # last ~24 points (~last day of the 7d series)
            }
        return out

stormchaser/trading/exchange.py:
"""PaperExchange — the ONLY execution path in this codebase, for both GHOST
and COPILOT modes.

There is deliberately no live adapter, no private-key handling, no
@solana/web3.js, no WalletConnect/Phantom RPC call, and no signing code
anywhere in this project. That is a direct response to
../../solana-bot/INCIDENT_REPORT.md (a real SOL loss from a live automated
memecoin-sniping bot in May 2026, wallet key burned, "do not resume live
automated trading of new-launch meme coins").

GHOST and COPILOT both fill through this exact function, against the real
live price from DataHub, with a slippage + fee model, against a simulated
SOL balance. The only difference between the two modes anywhere in this app
is presentation: COPILOT frames a fill as "approve this suggested trade"
(trading/copilot.py) before calling execute() with the same effect as a
direct GHOST buy/sell. Neither mode can ever move a real lamport.

Orders are one-shot: execute() always returns a definitive `filled` or
`rejected` result before the caller sees anything — no 'pending' escape
hatch, no retry loop. Those two failure modes are exactly what the incident
report traces the SolSniper loss to.
"""
from __future__ import annotations

import time

from ..config import Settings
from ..data.hub import DataHub
from ..db import Database
from .portfolio import Portfolio


class PaperExchange:
    def __init__(self, db: Database, hub: DataHub, portfolio: Portfolio, cfg: Settings):
        self.db = db
        self.hub = hub
        self.portfolio = portfolio
        self.cfg = cfg

    def _price_of(self, symbol: str) -> tuple[float | None, float | None]:
        """(price_usd, liquidity_usd) for a symbol, live from the hub cache."""
        if symbol == "SOL":
            return self.hub.major("solana").get("price_usd"), None
        if symbol == "BTC":
            return self.hub.major("bitcoin").get("price_usd"), None
        t = self.hub.token_by_symbol(symbol)
        if not t:
            return None, None
        return t["price_usd"], t.get("liquidity_usd")

    def _slippage_bps(self, liquidity_usd: float | None) -> int:
        if liquidity_usd is None:
            return self.cfg.base_slippage_bps
        if liquidity_usd <= 0:
            return self.cfg.meme_slippage_bps
        return min(self.cfg.meme_slippage_bps,
                   max(self.cfg.base_slippage_bps, int(1e4 * 200 / liquidity_usd)))

    def execute(self, *, wallet_id: int, mode: str, symbol: str, address: str, side: str,
               sol_amount: float | None = None, qty: float | None = None,
               blocked: bool = False, block_reason: str = "",
               stop: float | None = None, target: float | None = None,
               setup_note: str | None = None) -> dict:
        now = time.time()

        def reject(reason: str) -> dict:
            order_id = self.db.create_order(
                wallet_id=wallet_id, mode=mode, symbol=symbol, side=side,
                sol_amount=sol_amount, qty=qty, status="rejected", reject_reason=reason,
                requested_price=None, fill_price=None, slippage_bps=None,
                position_id=None, created_at=now)
            return {"order_id": order_id, "status": "rejected", "reject_reason": reason}

        if blocked:
            return reject(block_reason or "blocked")

        price, liq = self._price_of(symbol)
        if not price:
            return reject("no fresh price — refusing to fill blind")

        slip_bps = self._slippage_bps(liq)
        slip = slip_bps / 10_000
        fee_rate = self.cfg.fee_bps / 10_000
        wallet = self.db.get_wallet(wallet_id)
        if wallet is None:
            return reject("unknown wallet")

        if side == "buy":
            amt = sol_amount or 0.0
            if amt < self.cfg.min_order_sol:
                return reject(f"below min order {self.cfg.min_order_sol} SOL")
            if amt > self.cfg.max_order_sol:
                return reject(f"above max order cap {self.cfg.max_order_sol} SOL")
            open_positions = self.db.open_positions(wallet_id)
            if len(open_positions) >= self.cfg.max_concurrent_positions and \
               not any(p["symbol"] == symbol for p in open_positions):
                return reject(f"max {self.cfg.max_concurrent_positions} concurrent positions")
            fill_price = price * (1 + slip)
            fee = amt * fee_rate
            if wallet["balance_sol"] < amt + fee:
                return reject(f"insufficient GHOST balance ({wallet['balance_sol']:.3f} SOL)")
            fill_qty = (amt - fee) / fill_price
        else:
            open_pos = [p for p in self.db.open_positions(wallet_id) if p["symbol"] == symbol]
            if not open_pos:
                return reject("no open position")
            pos = open_pos[0]
            fill_qty = qty if qty is not None else pos["qty"]
            if fill_qty <= 0 or fill_qty > pos["qty"] + 1e-9:
                return reject("sell qty exceeds position")
            fill_price = price * (1 - slip)
            gross = fill_qty * fill_price
            fee = gross * fee_rate
            amt = gross - fee

        order_id = self.db.create_order(
            wallet_id=wallet_id, mode=mode, symbol=symbol, side=side,
            sol_amount=amt, qty=fill_qty, status="filled", reject_reason=None,
            requested_price=price, fill_price=fill_price, slippage_bps=slip_bps,
            position_id=None, created_at=now)

        try:
            position = self.portfolio.apply_fill(
                order_id=order_id, wallet_id=wallet_id, mode=mode, symbol=symbol,
                address=address, side=side, qty=fill_qty, fill_price=fill_price,
                sol_amount=amt, stop=stop, target=target, setup_note=setup_note)
        except ValueError as e:
            return reject(str(e))

        return {
            "order_id": order_id, "status": "filled", "side": side, "symbol": symbol,
            "fill_price": fill_price, "qty": fill_qty, "sol_amount": amt,
            "slippage_bps": slip_bps, "position": position,
        }
